struct AdminAccommodationOption: Identifiable, Codable {
    let id: String
    let priority: Int
    let hotel: AdminHotel
    let bookingInstructions: String?
    let recommendedReason: String?
    
    var effectiveBookingInstructions: String? {
        if let inst = bookingInstructions, !inst.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return inst
        }
        if let hotelInst = hotel.bookingInstructions, !hotelInst.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            return hotelInst
        }
        return nil
    }
    
    enum CodingKeys: String, CodingKey {
        case id, priority, hotel, bookingInstructions, recommendedReason
    }
    
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        id = try container.decodeIfPresent(String.self, forKey: .id) ?? UUID().uuidString
        priority = try container.decodeIfPresent(Int.self, forKey: .priority) ?? 1
        hotel = try container.decode(AdminHotel.self, forKey: .hotel)
        bookingInstructions = try container.decodeIfPresent(String.self, forKey: .bookingInstructions)
        recommendedReason = try container.decodeIfPresent(String.self, forKey: .recommendedReason)
    }
}

struct AdminHotel: Codable {
    let name: String
    let rating: Double
    let pricePerNight: Double
    let pointsPerNight: Int?
    let loyaltyProgram: String?
    let location: String
    let bookingUrl: String
    let bookingInstructions: String?
    let detailedDescription: String
    let amenities: [String]?
    let cancellationPolicy: String?
    let contactInfo: String?
    let photoUrl: String?
    let photos: [String]?
    let tripadvisorId: String?
    let tripadvisorUrl: String?
    
    enum CodingKeys: String, CodingKey {
        case name, rating, pricePerNight, pointsPerNight, loyaltyProgram
        case location, bookingUrl, bookingInstructions, detailedDescription
        case amenities, cancellationPolicy, contactInfo
        case photoUrl, photos, tripadvisorId, tripadvisorUrl
    }
    
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        
        name = try container.decodeIfPresent(String.self, forKey: .name) ?? ""
        location = try container.decodeIfPresent(String.self, forKey: .location) ?? ""
        bookingUrl = try container.decodeIfPresent(String.self, forKey: .bookingUrl) ?? ""
        bookingInstructions = try container.decodeIfPresent(String.self, forKey: .bookingInstructions)
        detailedDescription = try container.decodeIfPresent(String.self, forKey: .detailedDescription) ?? ""
        amenities = try container.decodeIfPresent([String].self, forKey: .amenities)
        cancellationPolicy = try container.decodeIfPresent(String.self, forKey: .cancellationPolicy)
        contactInfo = try container.decodeIfPresent(String.self, forKey: .contactInfo)
        photoUrl = try container.decodeIfPresent(String.self, forKey: .photoUrl)
        photos = try container.decodeIfPresent([String].self, forKey: .photos)
        tripadvisorId = try container.decodeIfPresent(String.self, forKey: .tripadvisorId)
        tripadvisorUrl = try container.decodeIfPresent(String.self, forKey: .tripadvisorUrl)
        
        if let ptsInt = try? container.decodeIfPresent(Int.self, forKey: .pointsPerNight) {
            pointsPerNight = ptsInt
        } else if let ptsDouble = try? container.decodeIfPresent(Double.self, forKey: .pointsPerNight), !ptsDouble.isNaN {
            pointsPerNight = Int(ptsDouble)
        } else {
            pointsPerNight = nil
        }
        
        loyaltyProgram = try container.decodeIfPresent(String.self, forKey: .loyaltyProgram)
        
        let rawRating = try container.decodeIfPresent(Double.self, forKey: .rating) ?? 4.0
        rating = rawRating.isNaN || rawRating.isInfinite ? 4.0 : rawRating
        
        let rawPrice = try container.decodeIfPresent(Double.self, forKey: .pricePerNight) ?? 0.0
        pricePerNight = rawPrice.isNaN || rawPrice.isInfinite ? 0.0 : rawPrice
    }
    
    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        
        try container.encode(name, forKey: .name)
        try container.encode(rating, forKey: .rating)
        try container.encode(pricePerNight, forKey: .pricePerNight)
        try container.encode(pointsPerNight, forKey: .pointsPerNight)
        try container.encode(loyaltyProgram, forKey: .loyaltyProgram)
        try container.encode(location, forKey: .location)
        try container.encode(bookingUrl, forKey: .bookingUrl)
        try container.encodeIfPresent(bookingInstructions, forKey: .bookingInstructions)
        try container.encode(detailedDescription, forKey: .detailedDescription)
        try container.encodeIfPresent(amenities, forKey: .amenities)
        try container.encodeIfPresent(cancellationPolicy, forKey: .cancellationPolicy)
        try container.encodeIfPresent(contactInfo, forKey: .contactInfo)
        try container.encode(photoUrl, forKey: .photoUrl)
        try container.encode(photos, forKey: .photos)
        try container.encode(tripadvisorId, forKey: .tripadvisorId)
        try container.encode(tripadvisorUrl, forKey: .tripadvisorUrl)
    }
}

struct AdminActivity: Identifiable, Codable {
    let id: String
    let name: String
    let description: String
    let location: String
    let estimatedCost: Double
    let estimatedDuration: String
    let category: String
    let priority: Int?
    let bestTimeToVisit: String?
    let bookingRequired: Bool?
    let bookingInstructions: String?
    let tips: String?
    let website: String?
    let tripadvisorUrl: String?
    let yelpUrl: String?
    let bookingUrl: String?
    
    enum CodingKeys: String, CodingKey {
        case id, name, description, location, estimatedCost, estimatedDuration, category
        case priority, bestTimeToVisit, bookingRequired, bookingInstructions, tips
        case website, tripadvisorUrl, yelpUrl, bookingUrl
    }
    
    private enum LocationKeys: String, CodingKey {
        case name, address, coordinates, nearbyLandmarks
    }
    
    private enum CostKeys: String, CodingKey {
        case cashAmount, totalCashValue, pointsAmount, pointsProgram, paymentType, notes
    }
    
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        
        id = try container.decodeIfPresent(String.self, forKey: .id) ?? UUID().uuidString
        name = try container.decodeIfPresent(String.self, forKey: .name) ?? ""
        description = try container.decodeIfPresent(String.self, forKey: .description) ?? ""
        estimatedDuration = try container.decodeIfPresent(String.self, forKey: .estimatedDuration) ?? ""
        category = try container.decodeIfPresent(String.self, forKey: .category) ?? ""
        priority = try? container.decodeIfPresent(Int.self, forKey: .priority)
        bestTimeToVisit = try? container.decodeIfPresent(String.self, forKey: .bestTimeToVisit)
        bookingRequired = try? container.decodeIfPresent(Bool.self, forKey: .bookingRequired)
        bookingInstructions = try? container.decodeIfPresent(String.self, forKey: .bookingInstructions)
        tips = try? container.decodeIfPresent(String.self, forKey: .tips)
        website = try container.decodeIfPresent(String.self, forKey: .website)
        tripadvisorUrl = try container.decodeIfPresent(String.self, forKey: .tripadvisorUrl)
        yelpUrl = try? container.decodeIfPresent(String.self, forKey: .yelpUrl)
        bookingUrl = try container.decodeIfPresent(String.self, forKey: .bookingUrl)
        
        if let locationString = try? container.decodeIfPresent(String.self, forKey: .location) {
            location = locationString
        } else {
            do {
                let locationContainer = try container.nestedContainer(keyedBy: LocationKeys.self, forKey: .location)
                let locName = (try? locationContainer.decodeIfPresent(String.self, forKey: .name))?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                let locAddr = (try? locationContainer.decodeIfPresent(String.self, forKey: .address))?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                if !locName.isEmpty && !locAddr.isEmpty && !locAddr.localizedCaseInsensitiveContains(locName) {
                    location = "\(locName), \(locAddr)"
                } else if !locAddr.isEmpty {
                    location = locAddr
                } else {
                    location = locName
                }
            } catch {
                location = ""
            }
        }
        
        if let costDouble = try? container.decodeIfPresent(Double.self, forKey: .estimatedCost) {
            estimatedCost = costDouble.isNaN || costDouble.isInfinite ? 0.0 : costDouble
        } else {
            do {
                let costContainer = try container.nestedContainer(keyedBy: CostKeys.self, forKey: .estimatedCost)
                let cashAmount = try? costContainer.decodeIfPresent(Double.self, forKey: .cashAmount) ?? 0.0
                let totalCashValue = try? costContainer.decodeIfPresent(Double.self, forKey: .totalCashValue) ?? 0.0
                let rawCost = max(cashAmount ?? 0.0, totalCashValue ?? 0.0)
                estimatedCost = rawCost.isNaN || rawCost.isInfinite ? 0.0 : rawCost
            } catch {
                estimatedCost = 0.0
            }
        }
    }
    
    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        
        try container.encode(id, forKey: .id)
        try container.encode(name, forKey: .name)
        try container.encode(description, forKey: .description)
        try container.encode(location, forKey: .location)
        try container.encode(estimatedCost, forKey: .estimatedCost)
        try container.encode(estimatedDuration, forKey: .estimatedDuration)
        try container.encode(category, forKey: .category)
        try container.encodeIfPresent(priority, forKey: .priority)
        try container.encodeIfPresent(bestTimeToVisit, forKey: .bestTimeToVisit)
        try container.encodeIfPresent(bookingRequired, forKey: .bookingRequired)
        try container.encodeIfPresent(bookingInstructions, forKey: .bookingInstructions)
        try container.encodeIfPresent(tips, forKey: .tips)
        try container.encode(website, forKey: .website)
        try container.encode(tripadvisorUrl, forKey: .tripadvisorUrl)
        try container.encodeIfPresent(yelpUrl, forKey: .yelpUrl)
        try container.encode(bookingUrl, forKey: .bookingUrl)
    }
}

struct AdminRestaurant: Identifiable, Codable {
    let id: String
    let name: String
    let cuisine: String
    let mealType: String?
    let priority: Int?
    let location: String
    let priceRange: String
    let estimatedCost: Double?
    let description: String
    let reservationRequired: Bool?
    let reservationUrl: String?
    let reservationInstructions: String?
    let specialties: String?
    let tips: String?
    let yelpUrl: String?
    let tripadvisorUrl: String?
    let website: String?
    
    enum CodingKeys: String, CodingKey {
        case id, name, cuisine, mealType, priority, location, priceRange, estimatedCost, description
        case reservationRequired, reservationUrl, reservationInstructions, specialties, tips
        case yelpUrl, tripadvisorUrl, website
    }
    
    private enum LocationKeys: String, CodingKey {
        case name, address, coordinates, nearbyLandmarks
    }
    
    private enum CostKeys: String, CodingKey {
        case cashAmount, totalCashValue
    }
    
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        
        id = try container.decodeIfPresent(String.self, forKey: .id) ?? UUID().uuidString
        name = try container.decodeIfPresent(String.self, forKey: .name) ?? ""
        cuisine = try container.decodeIfPresent(String.self, forKey: .cuisine) ?? ""
        mealType = try? container.decodeIfPresent(String.self, forKey: .mealType)
        priority = try? container.decodeIfPresent(Int.self, forKey: .priority)
        priceRange = try container.decodeIfPresent(String.self, forKey: .priceRange) ?? ""
        description = try container.decodeIfPresent(String.self, forKey: .description) ?? ""
        reservationRequired = try? container.decodeIfPresent(Bool.self, forKey: .reservationRequired)
        reservationUrl = try? container.decodeIfPresent(String.self, forKey: .reservationUrl)
        reservationInstructions = try? container.decodeIfPresent(String.self, forKey: .reservationInstructions)
        specialties = try? container.decodeIfPresent(String.self, forKey: .specialties)
        tips = try? container.decodeIfPresent(String.self, forKey: .tips)
        yelpUrl = try container.decodeIfPresent(String.self, forKey: .yelpUrl)
        tripadvisorUrl = try? container.decodeIfPresent(String.self, forKey: .tripadvisorUrl)
        website = try container.decodeIfPresent(String.self, forKey: .website)
        
        if let costDouble = try? container.decodeIfPresent(Double.self, forKey: .estimatedCost) {
            estimatedCost = costDouble.isNaN || costDouble.isInfinite ? nil : costDouble
        } else if let costContainer = try? container.nestedContainer(keyedBy: CostKeys.self, forKey: .estimatedCost) {
            let cash = (try? costContainer.decodeIfPresent(Double.self, forKey: .cashAmount)) ?? 0.0
            estimatedCost = cash > 0 ? cash : nil
        } else {
            estimatedCost = nil
        }
        
        if let locationString = try? container.decodeIfPresent(String.self, forKey: .location) {
            location = locationString
        } else {
            do {
                let locationContainer = try container.nestedContainer(keyedBy: LocationKeys.self, forKey: .location)
                let locName = (try? locationContainer.decodeIfPresent(String.self, forKey: .name))?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                let locAddr = (try? locationContainer.decodeIfPresent(String.self, forKey: .address))?.trimmingCharacters(in: .whitespacesAndNewlines) ?? ""
                if !locName.isEmpty && !locAddr.isEmpty && !locAddr.localizedCaseInsensitiveContains(locName) {
                    location = "\(locName), \(locAddr)"
                } else if !locAddr.isEmpty {
                    location = locAddr
                } else {
                    location = locName
                }
            } catch {
                location = ""
            }
        }
    }
    
    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        
        try container.encode(id, forKey: .id)
        try container.encode(name, forKey: .name)
        try container.encode(cuisine, forKey: .cuisine)
        try container.encodeIfPresent(mealType, forKey: .mealType)
        try container.encodeIfPresent(priority, forKey: .priority)
        try container.encode(location, forKey: .location)
        try container.encode(priceRange, forKey: .priceRange)
        try container.encodeIfPresent(estimatedCost, forKey: .estimatedCost)
        try container.encode(description, forKey: .description)
        try container.encodeIfPresent(reservationRequired, forKey: .reservationRequired)
        try container.encodeIfPresent(reservationUrl, forKey: .reservationUrl)
        try container.encodeIfPresent(reservationInstructions, forKey: .reservationInstructions)
        try container.encodeIfPresent(specialties, forKey: .specialties)
        try container.encodeIfPresent(tips, forKey: .tips)
        try container.encode(yelpUrl, forKey: .yelpUrl)
        try container.encodeIfPresent(tripadvisorUrl, forKey: .tripadvisorUrl)
        try container.encode(website, forKey: .website)
    }
}

struct AdminLogistics: Codable {
    let transportSegments: [AdminTransportSegment]
    let bookingDeadlines: [AdminBookingDeadline]
    let generalInstructions: String
    
    enum CodingKeys: String, CodingKey {
        case transportSegments, bookingDeadlines, generalInstructions
    }
    
    init() {
        transportSegments = []
        bookingDeadlines = []
        generalInstructions = ""
    }
    
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        
        transportSegments = try container.decodeIfPresent([AdminTransportSegment].self, forKey: .transportSegments) ?? []
        bookingDeadlines = try container.decodeIfPresent([AdminBookingDeadline].self, forKey: .bookingDeadlines) ?? []
        generalInstructions = try container.decodeIfPresent(String.self, forKey: .generalInstructions) ?? ""
    }
    
    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        
        try container.encode(transportSegments, forKey: .transportSegments)
        try container.encode(bookingDeadlines, forKey: .bookingDeadlines)
        try container.encode(generalInstructions, forKey: .generalInstructions)
    }
}

struct AdminTransportSegment: Identifiable, Codable {
    let id: String
    let fromCity: String
    let toCity: String
    let departureDate: String
    let transportOptions: [AdminTransportOption]
    let selectedOptionId: String?
    let segmentType: String?
    let bookingGroupId: String?
    let displaySequence: Int?
    let notes: String?
    
    var route: String {
        return "\(fromCity) → \(toCity)"
    }
    
    var date: String {
        return departureDate
    }
    
    enum CodingKeys: String, CodingKey {
        case id, fromCity, toCity, departureDate, dateRange, transportOptions, selectedOptionId
        case segmentType, bookingGroupId, displaySequence, notes
        case route, date
    }
    
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        
        id = try container.decodeIfPresent(String.self, forKey: .id) ?? UUID().uuidString
        
        if let fromCity = try container.decodeIfPresent(String.self, forKey: .fromCity),
           let toCity = try container.decodeIfPresent(String.self, forKey: .toCity) {
            self.fromCity = fromCity
            self.toCity = toCity
        } else if let route = try container.decodeIfPresent(String.self, forKey: .route) {
            let components = route.components(separatedBy: " → ")
            self.fromCity = components.first ?? route
            self.toCity = components.count > 1 ? components[1] : ""
        } else {
            self.fromCity = ""
            self.toCity = ""
        }
        
        if let newDate = try container.decodeIfPresent(String.self, forKey: .departureDate), !newDate.isEmpty {
            departureDate = newDate
        } else if let dateRange = try container.decodeIfPresent(String.self, forKey: .dateRange), !dateRange.isEmpty {
            departureDate = dateRange
        } else if let legacyDate = try container.decodeIfPresent(String.self, forKey: .date) {
            departureDate = legacyDate
        } else {
            departureDate = ""
        }
        
        transportOptions = try container.decodeIfPresent([AdminTransportOption].self, forKey: .transportOptions) ?? []
        selectedOptionId = try container.decodeIfPresent(String.self, forKey: .selectedOptionId)
        segmentType = try container.decodeIfPresent(String.self, forKey: .segmentType)
        bookingGroupId = try container.decodeIfPresent(String.self, forKey: .bookingGroupId)
        displaySequence = try container.decodeIfPresent(Int.self, forKey: .displaySequence)
        notes = try? container.decodeIfPresent(String.self, forKey: .notes)
    }
    
    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        
        try container.encode(id, forKey: .id)
        try container.encode(fromCity, forKey: .fromCity)
        try container.encode(toCity, forKey: .toCity)
        try container.encode(departureDate, forKey: .departureDate)
        try container.encode(transportOptions, forKey: .transportOptions)
        try container.encode(selectedOptionId, forKey: .selectedOptionId)
        try container.encode(segmentType, forKey: .segmentType)
        try container.encode(bookingGroupId, forKey: .bookingGroupId)
        try container.encode(displaySequence, forKey: .displaySequence)
        try container.encodeIfPresent(notes, forKey: .notes)
        try container.encode(route, forKey: .route)
        try container.encode(date, forKey: .date)
    }
}

struct AdminTransportOption: Identifiable, Codable {
    let id: String
    let transportType: String
    let priority: Int
    let cost: AdminTransportCost
    let details: AdminFlightDetails
    let duration: String
    let bookingUrl: String
    let notes: String
    let isRoundTrip: Bool?
    let linkedSegmentId: String?
    let recommendedSelection: Bool?
    
    enum CodingKeys: String, CodingKey {
        case id, transportType, type, priority, cost, details, duration, bookingUrl, notes
        case isRoundTrip, linkedSegmentId, recommendedSelection
    }
    
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        
        id = try container.decodeIfPresent(String.self, forKey: .id) ?? UUID().uuidString
        if let tType = try? container.decodeIfPresent(String.self, forKey: .transportType), !tType.isEmpty {
            transportType = tType == "car_rental" ? "car" : tType
        } else if let legacyType = try? container.decodeIfPresent(String.self, forKey: .type), !legacyType.isEmpty {
            transportType = legacyType == "car_rental" ? "car" : legacyType
        } else {
            transportType = "flight"
        }
        priority = try container.decodeIfPresent(Int.self, forKey: .priority) ?? 1
        cost = (try? container.decodeIfPresent(AdminTransportCost.self, forKey: .cost)) ?? AdminTransportCost()
        details = (try? container.decodeIfPresent(AdminFlightDetails.self, forKey: .details)) ?? AdminFlightDetails()
        duration = try container.decodeIfPresent(String.self, forKey: .duration) ?? ""
        bookingUrl = try container.decodeIfPresent(String.self, forKey: .bookingUrl) ?? ""
        notes = try container.decodeIfPresent(String.self, forKey: .notes) ?? ""
        
        do {
            isRoundTrip = try container.decodeIfPresent(Bool.self, forKey: .isRoundTrip)
        } catch {
            if let intValue = try? container.decodeIfPresent(Int.self, forKey: .isRoundTrip) {
                isRoundTrip = intValue == 1
            } else {
                isRoundTrip = nil
            }
        }
        
        if container.contains(.linkedSegmentId) {
            linkedSegmentId = try? container.decodeIfPresent(String.self, forKey: .linkedSegmentId)
        } else {
            linkedSegmentId = nil
        }
        
        do {
            recommendedSelection = try container.decodeIfPresent(Bool.self, forKey: .recommendedSelection)
        } catch {
            if let intValue = try? container.decodeIfPresent(Int.self, forKey: .recommendedSelection) {
                recommendedSelection = intValue == 1
            } else {
                recommendedSelection = nil
            }
        }
    }
    
    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        
        try container.encode(id, forKey: .id)
        try container.encode(transportType, forKey: .transportType)
        try container.encode(priority, forKey: .priority)
        try container.encode(cost, forKey: .cost)
        try container.encode(details, forKey: .details)
        try container.encode(duration, forKey: .duration)
        try container.encode(bookingUrl, forKey: .bookingUrl)
        try container.encode(notes, forKey: .notes)
        try container.encode(isRoundTrip, forKey: .isRoundTrip)
        try container.encode(linkedSegmentId, forKey: .linkedSegmentId)
        try container.encode(recommendedSelection, forKey: .recommendedSelection)
    }
}

struct AdminTransportCost: Codable {
    let paymentType: String
    let cashAmount: Double
    let totalCashValue: Double
    let pointsAmount: Int?
    let pointsProgram: String?
    let notes: String?
    
    var effectivePaymentType: String {
        let hasPoints = (pointsAmount ?? 0) > 0
        let hasCash = cashAmount > 0 || totalCashValue > 0
        
        if hasPoints && hasCash {
            return "mixed"
        } else if hasPoints {
            return "points"
        } else {
            return "cash"
        }
    }
    
    var displayPaymentType: String {
        switch effectivePaymentType {
        case "points":
            return "Points"
        case "mixed":
            return "Cash + Points"
        default:
            return "Cash"
        }
    }
    
    enum CodingKeys: String, CodingKey {
        case paymentType, cashAmount, totalCashValue, pointsAmount, pointsProgram, notes
    }
    
    init() {
        paymentType = "cash"
        cashAmount = 0.0
        totalCashValue = 0.0
        pointsAmount = nil
        pointsProgram = nil
        notes = nil
    }
    
    init(from decoder: Decoder) throws {
        // Handle simple numeric cost as fallback
        if let singleVal = try? decoder.singleValueContainer(),
           let doubleVal = try? singleVal.decode(Double.self) {
            paymentType = "cash"
            cashAmount = doubleVal.isNaN || doubleVal.isInfinite ? 0.0 : doubleVal
            totalCashValue = cashAmount
            pointsAmount = nil
            pointsProgram = nil
            notes = nil
            return
        }
        
        let container = try decoder.container(keyedBy: CodingKeys.self)
        
        paymentType = try container.decodeIfPresent(String.self, forKey: .paymentType) ?? "cash"
        if let ptsInt = try? container.decodeIfPresent(Int.self, forKey: .pointsAmount) {
            pointsAmount = ptsInt
        } else if let ptsDouble = try? container.decodeIfPresent(Double.self, forKey: .pointsAmount), !ptsDouble.isNaN {
            pointsAmount = Int(ptsDouble)
        } else {
            pointsAmount = nil
        }
        pointsProgram = try container.decodeIfPresent(String.self, forKey: .pointsProgram)
        notes = try? container.decodeIfPresent(String.self, forKey: .notes)
        
        let rawCash = try container.decodeIfPresent(Double.self, forKey: .cashAmount) ?? 0.0
        cashAmount = rawCash.isNaN || rawCash.isInfinite ? 0.0 : rawCash
        
        let rawTotal = try container.decodeIfPresent(Double.self, forKey: .totalCashValue) ?? 0.0
        totalCashValue = rawTotal.isNaN || rawTotal.isInfinite ? 0.0 : rawTotal
    }
    
    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        
        try container.encode(paymentType, forKey: .paymentType)
        try container.encode(cashAmount, forKey: .cashAmount)
        try container.encode(totalCashValue, forKey: .totalCashValue)
        try container.encode(pointsAmount, forKey: .pointsAmount)
        try container.encode(pointsProgram, forKey: .pointsProgram)
        try container.encodeIfPresent(notes, forKey: .notes)
    }
}

